import json
from pathlib import Path
r=Path("results/jacobian")
def load(p): return json.loads((r/p).read_text())
seed=load("corrected_seed_summary.json")
lines=["# JVP-Cal experiment report","","## Verdict","","The tested unanchored GGN configuration fails L0 on both settings: its clean accuracy is more than five percentage points below same-trajectory FedEraser E_cal=1. The single-seed anchored configuration meets the L0 thresholds in both settings. L1 and L2 are not demonstrated; a faithful FedRecover comparison and full-run FLOP measurements are unavailable. These are exploratory test-set results, not validation-selected results. Low ASR alone is not proof of unlearning.","","## Same-trajectory results","","| Setting | Method | CA % | ASR % | Round processing seconds |","|---|---|---:|---:|---:|"]
for setting in ("iid","noniid"):
 attack=load(setting+"_attack_logged/final_results.json")
 lines.append(f"| {setting} | attack | {attack['clean_accuracy']:.2f} | {attack['triggered_rate']:.2f} | {attack['runtime_seconds']:.2f} (full attack run) |")
 for method,folder in [("stale",setting+"_stale"),("FedEraser Ecal=1","corrected_"+setting+"_fed_e1"),("FedEraser Ecal=2","corrected_"+setting+"_fed_e2")]:
  m=load(folder+"/metrics.json"); lines.append(f"| {setting} | {method} | {m['ca']:.2f} | {m['asr']:.2f} | {m['runtime_s']:.2f} |")
 s=seed[setting]
 lines.append(f"| {setting} | GGN seed mean +/- sample SD | {s['ca']['mean']:.2f} +/- {s['ca']['sample_std']:.2f} | {s['asr']['mean']:.2f} +/- {s['asr']['sample_std']:.2f} | {s['runtime_s']['mean']:.2f} +/- {s['runtime_s']['sample_std']:.2f} |")
 for label,folder in [("GGN midpoint","corrected_"+setting+"_ggn_midpoint"),("GGN steps=158","corrected_"+setting+"_ggn_steps158"),("GGN anchor every 5, warmup 2","followup_"+setting+"_anchor5_w2"),("stale anchor every 5, warmup 2","followup_"+setting+"_stale_anchor5_w2")]:
  f=r/folder/"metrics.json"
  if f.exists():
   m=json.loads(f.read_text());lines.append(f"| {setting} | {label}, seed 123 | {m['ca']:.2f} | {m['asr']:.2f} | {m['runtime_s']:.2f} |")
lines += ["","Processing time is a sum of per-round wall times and excludes setup and evaluation; attack time is from its complete run and is not directly comparable. Values come from per-run JSON. FedEraser uses this repo's calibration logic in a new resumable runner, with different random seeds than the original baseline script. M_CF, M_sub and FedRecover B2 are not available as paired measurements; historical summaries are not mixed into this table.","","## Oracle diagnostic",""]
o=load("corrected_iid_oracle_summary.json")
lines += [f"For {o['count']} selected IID round/client pairs, stale vs unscaled GGN mean cosine was {o['cos_stale']:.5f} vs {o['cos_jvp']:.5f}; relative error was {o['relerr_stale']:.5f} vs {o['relerr_jvp']:.5f}. This small average improvement is not evidence of a robust benefit. See corrected_iid_oracle_sample.json and corrected_iid_oracle.png. The oracle uses eight examples, two full local epochs with fixed client order, and no norm rescaling; it does not exactly reproduce the 64-example rescaled estimator, and is not an exhaustive per-client diagnostic.","","## Method, credibility and limitations","","The estimator computes softmax generalized Gauss-Newton products using torch.func JVP/VJP and can compute exact Hessian products with double backward. The corrected replay uses the difference between replayed and stored global parameters, a fixed client subsample, eval-mode BatchNorm, historical buffer deltas and global norm rescaling. The default one-step coefficient is not an approximation validated for the true momentum SGD trajectory. A 158-step coefficient is an exploratory stress test, not a momentum correction. Anchor runs use actual one-epoch calibration. Four unit tests passed in logs/corrected_pipeline.log.","","FedRecover already estimates updates from historical information using L-BFGS and correction; general historical Taylor/Hessian estimation is not novel. See docs/jacobian/NOVELTY_CHECK.md. Only one attack seed per partition, CIFAR-10 and SmallCNN are available. Test results have been observed; no held-out validation-based tuning was done. Train-mode curvature, BN recomputation, a faithful B2 implementation, per-class ASR, full FLOP accounting and server storage costs are incomplete. Resume checkpoints restore model weights but not random generator state. Anchor results and earlier seed runs should be treated as exploratory. The matched anchor schedules use the same nominal seed, but JVP data access consumes random numbers, so client augmentation is not strictly paired. The anchor comparison uses only one seed.","","An earlier runner mistakenly used the historical client update as the Taylor displacement, and named a two-epoch run iid_fed_e1. Its JVP results and old plots are invalid; use corrected_ or followup_ outputs. Earlier report claims have been withdrawn.","","## Reproduction","","Run from /home/teaching/isp with PYTHONPATH set to the repository root. The trajectory files must already exist. Use nohup setsid env PYTHONUNBUFFERED=1 bash scripts/proposed/run_all.sh > logs/corrected_pipeline.log 2>&1 < /dev/null &. Existing progress checkpoints and stage markers control resumption. For anchors use scripts/proposed/run_followup.sh. For the sampled oracle use scripts/proposed/oracle_diagnostic.py with --replay results/jacobian/corrected_iid_ggn_s123 and an unused --out path. Tests: /home/teaching/miniconda3/bin/python -m pytest -q tests/test_jvp_cal.py. Long jobs should be detached and logged.",""]
if (r/"followup_flop_probe.json").exists():
 lines += ["## FLOP probe","","A single batch operator-level probe is recorded in followup_flop_probe.json. FlopCounterMode omits some operators and the probe is not an end-to-end client FLOP measurement; no 3x FLOP claim is made.",""]
(r/"REPORT.md").write_text("\n".join(lines))
